扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: #!/usr/bin/env node
L2: // npm/npx shim: run the bundled Python package (stdlib only) with python3.
L3: const { spawn } = require("child_process");
L4: const path = require("path");
L5: 
L6: const root = path.join(__dirname, "..");
L7: const python = process.env.AGRES_PYTHON || "python3";
L8: const env = {
L9:   ...process.env,
L10:   PYTHONPATH:
L11:     root +
L12:     (process.env.PYTHONPATH ? path.delimiter + process.env.PYTHONPATH : ""),
L13: };
L14: 
L15: const child = spawn(python, ["-m", "agres", ...process.argv.slice(2)], {
L16:   stdio: "inherit",
L17:   env,
L18: });
L19: child.on("error", (err) => {
L20:   console.error(
L21:     `agres: could not start ${python}: ${err.message} (set AGRES_PYTHON to a Python >= 3.9)`,
L22:   );
L23:   process.exit(1);
L24: });
L25: child.on("close", (code) => process.exit(code ?? 0));
L26:

